-- PT103-S1-Q2. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT103-S1-Q2$batch05$ AND q.stimulus=$batch05$Lambert: The proposal to raise gasoline taxes to support mass transit networks is unfair. Why should drivers who will never use train or bus lines be forced to pay for them?

Keziah: You have misunderstood. The government has always spent far more, per user, from general revenue sources to fund highways than to fund mass transit. The additional revenue from the gasoline tax will simply allow the government to make its distribution of transportation funds more equitable.$batch05$ AND q.prompt=$batch05$Keziah uses which one of the following argumentative strategies in replying to Lambert?$batch05$ AND q.correct_choice=$batch05$A$batch05$) THEN RAISE EXCEPTION 'Question changed: PT103-S1-Q2'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT103-S1-Q2$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S1-Q2'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT103-S1-Q2$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$(Keziah) The gas tax is not unfair. It makes funding more equitable.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$The government has always spent far more per user on highways than on mass transit, out of general revenue.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$Lambert sees drivers paying for something they will not use. Keziah widens the frame: drivers have been getting more than their share for years, so this tax helps even things out. She does not deny Lambert's facts. She adds context that changes how the proposal looks.$batch05$), (3, $batch05$Goal$batch05$, $batch05$Adding background that makes the proposal look fairer.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT103-S1-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$"Elaborating the context" is the history of highway spending. "Place the proposal in a more favorable light" is calling it more equitable. Both halves fit.$batch05$), ($batch05$B$batch05$, $batch05$Keziah's case is about fairness between drivers and transit users, not that whatever helps society helps everyone.$batch05$), ($batch05$C$batch05$, $batch05$This is the most popular wrong answer. Keziah does challenge Lambert, but she argues on fairness, his own ground. She says the tax makes things *more equitable*. She accepts fairness as the test and argues the tax passes it.$batch05$), ($batch05$D$batch05$, $batch05$Keziah never says drivers will not pay more.$batch05$), ($batch05$E$batch05$, $batch05$She engages with Lambert directly, explaining his misunderstanding rather than refusing to argue.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT103-S1-Q2$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
